/**
 * Attachments and hitbox sets, read out of the `.mdl` header.
 *
 * The attachment matrix uses Source's `Rz * Ry * Rx` Euler order; the test rebuilds the
 * matrix from the returned angles with an independent quaternion path so a sign or axis swap
 * cannot pass unnoticed. `survivor_producer` has 30 attachments and 17 custom hitboxes;
 * `l4d_gift` has an auto-generated hitbox set, which must be detectable so a compile can
 * regenerate it instead of pinning it.
 */
import { describe, expect, it } from "vitest";
import {
  AUTOGENERATED_HITBOX,
  matrixToEuler,
  readAttachments,
  readHitboxSets,
} from "../../src/models/typescript/formats/mdlmeta.js";
import { openGameVpk } from "../../src/assets/typescript/game/vpkcontent.js";
import { ctx, has } from "../support/env.js";

type Matrix = [[number, number, number], [number, number, number], [number, number, number]];

const degrees = (value: number): number => (value * 180) / Math.PI;

function eulerToMatrix([roll, pitch, yaw]: [number, number, number]): Matrix {
  // Source's AngleQuaternion with R = Rz(yaw) * Ry(pitch) * Rx(roll).
  const sr = Math.sin(roll / 2);
  const cr = Math.cos(roll / 2);
  const sp = Math.sin(pitch / 2);
  const cp = Math.cos(pitch / 2);
  const sy = Math.sin(yaw / 2);
  const cy = Math.cos(yaw / 2);
  const x = sr * cp * cy - cr * sp * sy;
  const y = cr * sp * cy + sr * cp * sy;
  const z = cr * cp * sy - sr * sp * cy;
  const w = cr * cp * cy + sr * sp * sy;
  return [
    [1 - 2 * (y * y + z * z), 2 * (x * y - w * z), 2 * (x * z + w * y)],
    [2 * (x * y + w * z), 1 - 2 * (x * x + z * z), 2 * (y * z - w * x)],
    [2 * (x * z - w * y), 2 * (y * z + w * x), 1 - 2 * (x * x + y * y)],
  ];
}

describe.skipIf(!has.gameContent)("mdlmeta", () => {
  const mdl = (path: string): Buffer => openGameVpk(ctx.config.gameDir!)!.read(path)!;

  it("reads 30 attachments and rebuilds their matrices from the Euler angles", () => {
    const bytes = mdl("models/survivors/survivor_producer.mdl");
    const attachments = readAttachments(bytes);
    expect(attachments).toHaveLength(30);
    const eyes = attachments.find((attachment) => attachment.name === "eyes")!;
    expect(eyes.bone).toBe(16);
    expect(eyes.position[0]).toBeCloseTo(3.416, 3);
    expect(eyes.position[1]).toBeCloseTo(-2.357, 3);
    expect(eyes.position[2]).toBeCloseTo(0.053, 3);
    // The head's eye attachment is a 90-degree turn on two axes; the exact numbers came from
    // decompiling with Crowbar as a cross-check, but the matrix is the real proof.
    expect(degrees(eyes.rotation[0])).toBeCloseTo(-90, 0);
    expect(degrees(eyes.rotation[2])).toBeCloseTo(-89.37, 1);

    const offset = bytes.readInt32LE(244);
    let maxDifference = 0;
    for (const attachment of attachments) {
      const stored = eulerToMatrix([0, 0, 0]);
      for (let row = 0; row < 3; row += 1) {
        for (let column = 0; column < 3; column += 1) {
          stored[row]![column] = bytes.readFloatLE(offset + attachment.index * 92 + 12 + row * 16 + column * 4);
        }
      }
      const rebuilt = eulerToMatrix([
        attachment.rotation[0],
        attachment.rotation[1],
        attachment.rotation[2],
      ]);
      for (let row = 0; row < 3; row += 1) {
        for (let column = 0; column < 3; column += 1) {
          maxDifference = Math.max(
            maxDifference,
            Math.abs(rebuilt[row]![column]! - stored[row]![column]!),
          );
        }
      }
    }
    // A few shipped matrices carry a sub-millimetre scale; anything larger is an axis error.
    expect(maxDifference).toBeLessThan(1e-3);
  });

  it("reads custom hitboxes and ignores an auto-generated set", () => {
    const smoker = mdl("models/infected/smoker.mdl");
    const sets = readHitboxSets(smoker);
    expect(sets).toHaveLength(1);
    expect(sets[0]!.name).toBe("cstrike");
    expect(sets[0]!.hitboxes).toHaveLength(17);
    expect(sets[0]!.hitboxes[0]!.group).toBe(3);
    expect(sets[0]!.hitboxes[0]!.bone).toBe(0);
    expect(sets[0]!.hitboxes[0]!.min[0]).toBeCloseTo(-8.225, 3);

    const gift = mdl("models/items/l4d_gift.mdl");
    expect(gift.readInt32LE(152) & AUTOGENERATED_HITBOX).toBe(AUTOGENERATED_HITBOX);
    expect(readHitboxSets(gift)[0]!.hitboxes).toHaveLength(1);
  });

  it("returns plausible angles at the poles", () => {
    // A pure 90-degree pitch is the gimbal-lock branch: roll and yaw are not independent.
    const matrix = [0, 0, 1, 0, 1, 0, -1, 0, 0];
    const euler = matrixToEuler(matrix);
    expect(euler.every(Number.isFinite)).toBe(true);
    const rebuilt = eulerToMatrix([euler[0], euler[1], euler[2]]);
    expect(rebuilt[0]![2]).toBeCloseTo(1, 5);
    expect(rebuilt[1]![1]).toBeCloseTo(1, 5);
    expect(rebuilt[2]![0]).toBeCloseTo(-1, 5);
  });
});
